#!/usr/bin/env python3
import base64,json,time,urllib.request,urllib.parse,threading,queue,subprocess,os
from pathlib import Path
from cdp_ws import WSClient

HOME=Path.home()/".copytolive-chat-lokal"
TOKEN=(HOME/"token").read_text().strip()
BASE="http://127.0.0.1:8765"
PORTS=range(19401,19499)
HEADERS={"Content-Type":"application/json","X-CopyToLive-Token":TOKEN}
seen=set(); seen_lock=threading.Lock(); jobs=queue.Queue(maxsize=10000)
apple_lock=threading.RLock()
MAIN_HELPER=Path(__file__).resolve().with_name("chat_local_main_bridge.py")
try:
    _env=os.environ.copy(); _env["CHAT_LOCAL_INJECTOR_PID"]=str(os.getpid())
    subprocess.Popen(["/usr/bin/python3",str(MAIN_HELPER)],cwd=str(MAIN_HELPER.parent),env=_env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
except Exception:
    pass

def gj(url,timeout=1):
    with urllib.request.urlopen(url,timeout=timeout) as r:return json.load(r)
def http_post(path,obj,timeout=10):
    q=urllib.request.Request(BASE+path,data=json.dumps(obj,separators=(",",":")).encode(),method="POST",headers=HEADERS)
    with urllib.request.urlopen(q,timeout=timeout) as r:return json.load(r)
def http_get(path,timeout=10):
    q=urllib.request.Request(BASE+path,headers={"X-CopyToLive-Token":TOKEN})
    with urllib.request.urlopen(q,timeout=timeout) as r:return json.load(r)
def rpc(wsurl,method,params=None,timeout=4):
    with WSClient(wsurl,timeout=timeout) as ws:
        ws.send_json({"id":1,"method":method,"params":params or {}})
        while True:
            x=ws.recv_json()
            if x.get("id")==1:
                if "error" in x:raise RuntimeError(x["error"])
                return x.get("result",{})
def ev(wsurl,expr):
    r=rpc(wsurl,"Runtime.evaluate",{"expression":expr,"returnByValue":True,"userGesture":True})
    return r.get("result",{}).get("value")

SCAN_JS=r'''(() => {
 const out=[];
 const nodes=[...document.querySelectorAll('[data-message-author-role="assistant"]')];
 for(const n of nodes){
   const text=n.textContent||n.innerText||'';
   const re=/\[\[CHAT_LOCAL_REQUEST\]\]\s*([\s\S]*?)\s*\[\[\/CHAT_LOCAL_REQUEST\]\]/g;
   let m; while((m=re.exec(text)))out.push(m[1]);
   for(const a of n.querySelectorAll('a')){
     const h=a.getAttribute('href')||'';
     if(h.includes('#chat-local=')){
       const z=h.split('#chat-local=')[1]||'';
       try{out.push(decodeURIComponent(z));}catch(e){}
     }
   }
 }
 return out;
})()'''

SCAN_MAIN_JS=r'''(() => {
 const out=[];
 const nodes=[...document.querySelectorAll('[data-message-author-role="assistant"]')];
 for(const n of nodes){
   const text=n.textContent||n.innerText||'';
   const re=/\[\[CHAT_LOCAL_REQUEST\]\]\s*([\s\S]*?)\s*\[\[\/CHAT_LOCAL_REQUEST\]\]/g;
   let m; while((m=re.exec(text)))out.push(m[1]);
   for(const a of n.querySelectorAll('a')){
     const h=a.getAttribute('href')||'';
     if(h.includes('#chat-local=')){
       const z=h.split('#chat-local=')[1]||'';
       try{out.push(decodeURIComponent(z));}catch(e){}
     }
   }
 }
 return JSON.stringify(out);
})()'''

SEND_FN=r'''async function(text){
 function composer(){return document.querySelector('#prompt-textarea,[contenteditable="true"][data-virtualkeyboard],[contenteditable="true"][data-testid="prompt-textarea"]');}
 for(let i=0;i<60;i++){
   const el=composer();
   if(el){
     el.focus();
     if(el.isContentEditable){el.innerHTML='';document.execCommand('insertText',false,text);}
     else el.value=text;
     el.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:text}));
     await new Promise(r=>setTimeout(r,120));
     const b=document.querySelector('button[data-testid="send-button"],button[aria-label*="Send"],button[aria-label*="Kirim"]');
     if(b&&!b.disabled){b.click();return true;}
   }
   await new Promise(r=>setTimeout(r,150));
 }
 return false;
}'''

def osa(script,timeout=20):
    with apple_lock:
        p=subprocess.run(["/usr/bin/osascript","-e",script],capture_output=True,text=True,timeout=timeout)
    if p.returncode: raise RuntimeError((p.stderr or p.stdout).strip())
    return p.stdout.rstrip()

def scan_main_chrome():
    b=base64.b64encode(SCAN_MAIN_JS.encode()).decode()
    script=f'''
tell application "Google Chrome"
 set outText to ""
 repeat with wi from 1 to count of windows
  repeat with ti from 1 to count of tabs of window wi
   set u to URL of tab ti of window wi
   if u starts with "https://chatgpt.com/" then
    try
     set r to execute tab ti of window wi javascript "eval(atob('{b}'))"
     set outText to outText & u & tab & r & linefeed
    end try
   end if
  end repeat
 end repeat
 return outText
end tell
'''
    out=osa(script,25)
    rows=[]
    for line in out.splitlines():
        if "\t" not in line: continue
        url,raw=line.split("\t",1)
        try: arr=json.loads(raw)
        except Exception: continue
        if isinstance(arr,list): rows.append((url,arr))
    return rows

def main_ev_by_url(url,expr):
    b=base64.b64encode(expr.encode()).decode()
    uq=url.replace("\\","\\\\").replace('"','\\"')
    script=f'''
tell application "Google Chrome"
 repeat with wi from 1 to count of windows
  repeat with ti from 1 to count of tabs of window wi
   if URL of tab ti of window wi is "{uq}" then
    return execute tab ti of window wi javascript "eval(atob('{b}'))"
   end if
  end repeat
 end repeat
 return "__CHAT_LOCAL_TAB_NOT_FOUND__"
end tell
'''
    return osa(script,25)

def send_to_chat(wsurl,text):return bool(ev(wsurl,"("+SEND_FN+")("+json.dumps(text)+")"))
def send_to_main(url,text):
    r=main_ev_by_url(url,"("+SEND_FN+")("+json.dumps(text)+")")
    return str(r).lower()=="true"
def set_test_result(wsurl,obj):ev(wsurl,"window.__CHAT_LOKAL_LAST_TEST__="+json.dumps(obj,separators=(",",":"))+"; true")

def process_job(job):
    kind,locator,req=job
    rid=req.get("id") or f"chat-local-{int(time.time()*1000)}"; req["id"]=rid
    try:
        qid=http_post("/v1/enqueue",req)["id"]; deadline=time.time()+120; result=None
        while time.time()<deadline:
            st=http_get("/v1/result/"+urllib.parse.quote(qid,safe=""))
            if st.get("status") in ("done","error"):result=st.get("result");break
            time.sleep(.05)
        if result is None:result={"ok":False,"id":rid,"error":"Timeout","message":"local task timeout"}
    except Exception as e:result={"ok":False,"id":rid,"error":type(e).__name__,"message":str(e)}
    if req.get("_chat_local_test_only") and kind=="cdp":
        try:set_test_result(locator,result)
        except Exception:pass
        return
    msg="CHAT_LOCAL_RESULT "+rid+"\n"+json.dumps(result,ensure_ascii=False)
    try:
        if kind=="cdp": send_to_chat(locator,msg)
        else: send_to_main(locator,msg)
    except Exception:pass

def worker():
    while True:
        j=jobs.get()
        try:process_job(j)
        finally:jobs.task_done()

for _ in range(16):threading.Thread(target=worker,daemon=True).start()

last_main_scan=float('inf')
while True:
    for port in PORTS:
        try:arr=gj(f"http://127.0.0.1:{port}/json/list",.20)
        except Exception:continue
        for p in arr:
            url=p.get("url") or ""
            if p.get("type")!="page" or not url.startswith("https://chatgpt.com/"):continue
            wsurl=p.get("webSocketDebuggerUrl")
            try:raws=ev(wsurl,SCAN_JS) or []
            except Exception:continue
            for raw in raws:
                try:req=json.loads(raw)
                except Exception:continue
                if not isinstance(req,dict) or not req.get("op"):continue
                key=(url,str(req.get("id") or ""),raw)
                with seen_lock:
                    if key in seen:continue
                    seen.add(key)
                try:jobs.put_nowait(("cdp",wsurl,req))
                except queue.Full:
                    with seen_lock:seen.discard(key)

    now=time.time()
    if now-last_main_scan>=0.8:
        last_main_scan=now
        try:
            main_rows=scan_main_chrome()
            (Path(__file__).with_name("injector_main_status.json")).write_text(json.dumps({"ok":True,"time":time.time(),"rows":len(main_rows),"urls":[x[0] for x in main_rows]},ensure_ascii=False),encoding="utf-8")
        except Exception as e:
            main_rows=[]
            (Path(__file__).with_name("injector_main_status.json")).write_text(json.dumps({"ok":False,"time":time.time(),"error":type(e).__name__,"message":str(e)},ensure_ascii=False),encoding="utf-8")
        for url,raws in main_rows:
            for raw in raws:
                try:req=json.loads(raw)
                except Exception:continue
                if not isinstance(req,dict) or not req.get("op"):continue
                key=(url,str(req.get("id") or ""),raw)
                with seen_lock:
                    if key in seen:continue
                    seen.add(key)
                try:jobs.put_nowait(("main",url,req))
                except queue.Full:
                    with seen_lock:seen.discard(key)
    time.sleep(.25)

#!/usr/bin/env python3
import base64,json,os,subprocess,time,urllib.request,urllib.parse
from pathlib import Path

HOME=Path.home()/".copytolive-chat-lokal"
TOKEN=(HOME/"token").read_text().strip()
BASE="http://127.0.0.1:8765"
HERE=Path(__file__).resolve().parent
STATE=HOME/"main-bridge-seen.json"
STATUS=HERE/"main_bridge_status.json"
PARENT=int(os.environ.get("CHAT_LOCAL_INJECTOR_PID","0") or "0")
HEADERS={"Content-Type":"application/json","X-CopyToLive-Token":TOKEN}

SCAN_JS=r'''(() => {
 const out=[];
 const nodes=[...document.querySelectorAll('[data-message-author-role="assistant"]')];
 for(const n of nodes){
   const text=n.textContent||n.innerText||'';
   const re=/\[\[CHAT_LOCAL_REQUEST\]\]\s*([\s\S]*?)\s*\[\[\/CHAT_LOCAL_REQUEST\]\]/g;
   let m; while((m=re.exec(text))) out.push(m[1]);
   for(const a of n.querySelectorAll('a')){
     const h=a.getAttribute('href')||'';
     if(h.includes('#chat-local=')){
       const z=h.split('#chat-local=')[1]||'';
       try{out.push(decodeURIComponent(z));}catch(e){}
     }
   }
 }
 return JSON.stringify(out);
})()'''

def write_status(**kw):
    d={"online":True,"pid":os.getpid(),"parent":PARENT,"time":time.time()}
    d.update(kw)
    try: STATUS.write_text(json.dumps(d,ensure_ascii=False),encoding="utf-8")
    except Exception: pass

def parent_alive():
    if not PARENT:return True
    try: os.kill(PARENT,0); return True
    except OSError:return False

def osa(script,timeout=25):
    p=subprocess.run(["/usr/bin/osascript","-e",script],capture_output=True,text=True,timeout=timeout)
    if p.returncode: raise RuntimeError((p.stderr or p.stdout).strip())
    return p.stdout.rstrip()

def js_b64(code): return base64.b64encode(code.encode()).decode()

def scan_tabs():
    b=js_b64(SCAN_JS)
    script=f'''
tell application "Google Chrome"
 set outText to ""
 repeat with wi from 1 to count of windows
  repeat with ti from 1 to count of tabs of window wi
   set u to URL of tab ti of window wi
   if u starts with "https://chatgpt.com/" then
    try
     set r to execute tab ti of window wi javascript "eval(atob('{b}'))"
     set outText to outText & u & "|||CHATLOCAL|||" & r & linefeed
    end try
   end if
  end repeat
 end repeat
 return outText
end tell
'''
    out=osa(script)
    rows=[]
    for line in out.splitlines():
        if "|||CHATLOCAL|||" not in line:continue
        url,raw=line.split("|||CHATLOCAL|||",1)
        try: arr=json.loads(raw)
        except Exception:continue
        if isinstance(arr,list):rows.append((url,arr))
    return rows

def exec_url(url,code):
    b=js_b64(code); uq=url.replace("\\","\\\\").replace('"','\\"')
    script=f'''
tell application "Google Chrome"
 repeat with wi from 1 to count of windows
  repeat with ti from 1 to count of tabs of window wi
   if URL of tab ti of window wi is "{uq}" then
    return execute tab ti of window wi javascript "eval(atob('{b}'))"
   end if
  end repeat
 end repeat
 return "__CHAT_LOCAL_TAB_NOT_FOUND__"
end tell
'''
    return osa(script)

def send_text(url,text):
    payload=base64.b64encode(text.encode()).decode()
    code=rf'''(() => {{
 const text=new TextDecoder().decode(Uint8Array.from(atob("{payload}"),c=>c.charCodeAt(0)));
 const el=document.querySelector('#prompt-textarea,[contenteditable="true"][data-virtualkeyboard],[contenteditable="true"][data-testid="prompt-textarea"]');
 if(!el) return "NO_COMPOSER";
 el.focus();
 if(el.isContentEditable){{el.innerHTML="";document.execCommand("insertText",false,text);}}
 else {{el.value=text;}}
 el.dispatchEvent(new InputEvent("input",{{bubbles:true,inputType:"insertText",data:text}}));
 setTimeout(()=>{{
   const b=document.querySelector('button[data-testid="send-button"],button[aria-label*="Send"],button[aria-label*="Kirim"]');
   if(b&&!b.disabled)b.click();
 }},350);
 return "SCHEDULED";
}})()'''
    return exec_url(url,code)

def post(path,obj):
    q=urllib.request.Request(BASE+path,data=json.dumps(obj,separators=(",",":")).encode(),method="POST",headers=HEADERS)
    with urllib.request.urlopen(q,timeout=10) as r:return json.load(r)
def get(path):
    q=urllib.request.Request(BASE+path,headers={"X-CopyToLive-Token":TOKEN})
    with urllib.request.urlopen(q,timeout=10) as r:return json.load(r)

def execute(url,req):
    rid=str(req.get("id") or "")
    if not rid or not req.get("op"):return False
    try:
        qid=post("/v1/enqueue",req)["id"]; deadline=time.time()+180; result=None
        while time.time()<deadline:
            st=get("/v1/result/"+urllib.parse.quote(qid,safe=""))
            if st.get("status") in ("done","error"):
                result=st.get("result");break
            time.sleep(.08)
        if result is None:result={"ok":False,"id":rid,"error":"Timeout"}
    except Exception as e:
        result={"ok":False,"id":rid,"error":type(e).__name__,"message":str(e)}
    msg="CHAT_LOCAL_RESULT "+rid+"\n"+json.dumps(result,ensure_ascii=False)
    sr=send_text(url,msg)
    write_status(last_id=rid,last_url=url,last_send=sr)
    return sr=="SCHEDULED"

try:
    s=json.loads(STATE.read_text()) if STATE.exists() else {}
except Exception:s={}
if s.get("schema") != 2:
    s={}
seen=set(s.get("seen") or [])
initialized=bool(s.get("initialized"))

while parent_alive():
    try:
        rows=scan_tabs()
        urls=[u for u,_ in rows]
        current=[]
        for url,raws in rows:
            for raw in raws:
                try:req=json.loads(raw)
                except Exception:continue
                if not isinstance(req,dict) or not req.get("op"):continue
                rid=str(req.get("id") or "")
                if not rid:continue
                key=url+"|"+rid+"|"+raw
                current.append(key)
                if initialized and key not in seen:
                    ok=execute(url,req)
                    if ok:
                        seen.add(key)
                        STATE.write_text(json.dumps({"schema":2,"initialized":True,"seen":list(seen)[-5000:]},ensure_ascii=False))
        if not initialized:
            seen.update(current)
            initialized=True
            STATE.write_text(json.dumps({"schema":2,"initialized":True,"seen":list(seen)[-5000:]},ensure_ascii=False))
        write_status(rows=len(rows),urls=urls,initialized=initialized,seen=len(seen))
    except Exception as e:
        write_status(ok=False,error=type(e).__name__,message=str(e),initialized=initialized,seen=len(seen))
    time.sleep(.8)

write_status(online=False,reason="parent-exited",initialized=initialized,seen=len(seen))

#!/usr/bin/env python3
import base64,json,os,subprocess,time,urllib.request,urllib.parse
from pathlib import Path

SECRET="9F6K2M7Q4R8V3X1Z"
