DELIM="|||CTL3|||"

SCAN_JS=r'''(() => {
 const text=(document.body && (document.body.innerText||document.body.textContent)) || "";
 const out=[];
 const re=/\[\[CTL-9F6K2M7Q4R8V3X1Z\]\]\s*([A-Za-z0-9_-]+)\s*\[\[\/CTL-9F6K2M7Q4R8V3X1Z\]\]/g;
