def get(path):
    q=urllib.request.Request(BASE+path,headers={"X-CopyToLive-Token":TOKEN})
    with urllib.request.urlopen(q,timeout=10) as r:
        return json.load(r)

def decode_payload(s):
    s += "="*((4-len(s)%4)%4)
    return json.loads(base64.urlsafe_b64decode(s.encode()).decode())

try:
    st=json.loads(STATE.read_text()) if STATE.exists() else {}
except Exception:
    st={}
seen=set(st.get("seen") or [])

write_status(starting=True,seen=len(seen))
while True:
    try:
        rows=scan()
        for wi,ti,url,items in rows:
            for carrier in items:
                try:
                    req=decode_payload(carrier)
                except Exception:
                    continue
                if not isinstance(req,dict):
                    continue
                rid=str(req.get("id") or "")
                if not rid or not req.get("op") or rid in seen:
