                    result={"ok":False,"id":rid,"error":type(e).__name__,"message":str(e)}
                msg="CHAT_LOCAL_RESULT "+rid+"\n"+json.dumps(result,ensure_ascii=False)
                sr=send_text(wi,ti,msg)
                write_status(last_id=rid,last_url=url,last_send=sr,seen=len(seen),rows=len(rows))
